// ❌ OLD: Multiple roundtrips or complex client-side event buses
// to synchronize the navigation cart count, toast notifications, and button state.
async function handleAddToCart(productId) {
  await fetch(`/api/cart/add?id=${productId}`, { method: 'POST' });

  // Separate calls to refresh other UI components:
  const cartRes = await fetch('/api/cart/count');
  document.getElementById('cart-badge').innerHTML = await cartRes.text();

  const toastRes = await fetch('/api/toast/latest');
  document.getElementById('toasts').innerHTML = await toastRes.text();
}
